import re

_UNITS = {
    1: ("s", "sec", "secs", "second", "seconds"),
    60: ("m", "min", "mins", "minute", "minutes"),
    3600: ("h", "hr", "hrs", "hour", "hours"),
    86400: ("d", "day", "days"),
    604800: ("w", "wk", "wks", "week", "weeks"),
}
_UNIT_MAP = {name: mult for mult, names in _UNITS.items() for name in names}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_ISO_RE = re.compile(
    rf"P(?:({_NUM})W)?(?:({_NUM})D)?(?:T(?:({_NUM})H)?(?:({_NUM})M)?(?:({_NUM})S)?)?"
)
_COMPONENT_RE = re.compile(rf"\s*({_NUM})\s*([a-zA-Z]+)\s*")


def _round(total: float) -> int:
    return int(total + 0.5)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if s.isdigit():
        return int(s)

    # ISO 8601
    if s[0] in "Pp":
        up = s.upper()
        m = _ISO_RE.fullmatch(up)
        if not m or up in ("P", "PT") or up.endswith("T") or not any(m.groups()):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        mults = (604800, 86400, 3600, 60, 1)
        return _round(sum(float(g) * k for g, k in zip(m.groups(), mults) if g))

    # Clock notation
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3) or not all(re.fullmatch(r"\d+", p) for p in parts[:-1]) \
                or not re.fullmatch(_NUM, parts[-1]):
            raise ValueError(f"invalid clock duration: {text!r}")
        nums = [float(p) for p in parts]
        if len(nums) == 2:
            nums.insert(0, 0.0)
        h, mi, se = nums
        if len(parts) == 3 and mi >= 60:
            raise ValueError(f"invalid minutes: {text!r}")
        if se >= 60:
            raise ValueError(f"invalid seconds: {text!r}")
        return _round(h * 3600 + mi * 60 + se)

    # Number + unit components
    pos = 0
    total = 0.0
    while pos < len(s):
        m = _COMPONENT_RE.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNIT_MAP:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += float(m.group(1)) * _UNIT_MAP[unit]
        pos = m.end()
    return _round(total)

